<?php $page_title='Dashboard'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'dashboard','can_view');
$stats=[]; $stats['products']=(int)$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn(); $stats['warehouses']=(int)$pdo->query("SELECT COUNT(*) FROM warehouses")->fetchColumn(); $stats['customers']=(int)$pdo->query("SELECT COUNT(*) FROM customers")->fetchColumn(); $stats['suppliers']=(int)$pdo->query("SELECT COUNT(*) FROM suppliers")->fetchColumn();
$stats['stock']=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock")->fetchColumn(); $stats['sales']=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM sales WHERE status='completed'")->fetchColumn(); $stats['purchases']=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM purchases WHERE status='received'")->fetchColumn();
$low=$pdo->query("SELECT p.name, p.low_stock_threshold, COALESCE(SUM(s.quantity),0) as total FROM products p LEFT JOIN stock s ON s.product_id=p.id GROUP BY p.id HAVING total <= p.low_stock_threshold ORDER BY total ASC LIMIT 10")->fetchAll();
$recent_sales=$pdo->query("SELECT s.invoice_no, c.name as cust, s.total_amount, s.sale_date FROM sales s JOIN customers c ON c.id=s.customer_id ORDER BY s.id DESC LIMIT 8")->fetchAll();
$recent_pur=$pdo->query("SELECT p.purchase_no, sup.name as supp, p.total_amount, p.purchase_date FROM purchases p JOIN suppliers sup ON sup.id=p.supplier_id ORDER BY p.id DESC LIMIT 8")->fetchAll();
?>
<div class="row g-3 mb-3">
<?php foreach([['Total Products',$stats['products']],['Total Stock Units',$stats['stock']],['Total Sales',money($stats['sales'])],['Total Purchases',money($stats['purchases'])],['Customers',$stats['customers']],['Warehouses',$stats['warehouses']]] as $c): ?><div class="col-md-4 col-lg-2"><div class="card p-3"><small class="text-muted"><?= $c[0] ?></small><div class="stat"><?= $c[1] ?></div></div></div><?php endforeach; ?>
</div>
<div class="row g-3"><div class="col-md-6"><div class="card p-3"><h5>⚠️ Low Stock Alerts</h5><?php if(!$low): ?><p class="text-muted">No low stock items.</p><?php endif; ?><ul class="list-group"><?php foreach($low as $l): ?><li class="list-group-item d-flex justify-content-between"><?= e($l['name']) ?><span class="badge bg-danger"><?= (int)$l['total'] ?> left</span></li><?php endforeach; ?></ul></div></div>
<div class="col-md-6"><div class="card p-3"><h5>Recent Sales</h5><table class="table"><thead><tr><th>Invoice</th><th>Customer</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach($recent_sales as $r): ?><tr><td><?= e($r['invoice_no']) ?></td><td><?= e($r['cust']) ?></td><td><?= money($r['total_amount']) ?></td><td><?= e($r['sale_date']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="col-md-12"><div class="card p-3"><h5>Recent Purchases</h5><table class="table"><thead><tr><th>Purchase</th><th>Supplier</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach($recent_pur as $r): ?><tr><td><?= e($r['purchase_no']) ?></td><td><?= e($r['supp']) ?></td><td><?= money($r['total_amount']) ?></td><td><?= e($r['purchase_date']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
